      pt: ["Temporada: junho a novembro.", "Avistamentos anuais: 300.", "Comprimento das baleias: até 16 m.", "Peso: até 30 toneladas.", "Tamanho da zona: 200 km².", "Operadoras licenciadas."],
      fr: ["Saison : juin à novembre.", "Observations annuelles : 300.", "Longueur des baleines : jusqu'à 16 m.", "Poids : jusqu'à 30 tonnes.", "Taille de la zone : 200 km².", "Prestataires agréés."],
